# main.py
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import StreamingResponse, HTMLResponse
from pydantic import BaseModel, Field
from pydantic_settings import BaseSettings
from typing import List, Optional, Dict, Any, Literal, AsyncIterator
from datetime import datetime
from enum import Enum
import os
import json
import asyncio
import time
import re
from exa_py import Exa
from cerebras.cloud.sdk import Cerebras
from openai import AsyncOpenAI
from tenacity import retry, stop_after_attempt, wait_exponential


class Settings(BaseSettings):
    EXA_API_KEY: str
    XAI_API_KEY: str
    CEREBRAS_API_KEY: str

    class Config:
        env_file = ".env"
        case_sensitive = True


settings = Settings()


class ModelTier(str, Enum):
    FAST = "fast"
    BALANCED = "balanced"
    PREMIUM = "premium"


class ResearchRequest(BaseModel):
    query: str = Field(..., min_length=1, max_length=5000)
    depth: Literal["quick", "standard", "maximum"] = Field(default="standard")
    real_time: bool = Field(default=True)
    model_tier: ModelTier = Field(default=ModelTier.BALANCED)
    max_sources: int = Field(default=50, ge=1, le=100)
    domains: Optional[List[str]] = Field(default=None)
    exclude_domains: Optional[List[str]] = Field(default=None)


class Citation(BaseModel):
    url: str
    title: Optional[str] = None
    snippet: Optional[str] = None


class ResearchResult(BaseModel):
    synthesis: str
    citations: List[Citation]
    sources_analyzed: int
    tokens_used: Dict[str, int]
    cost_estimate: float
    processing_time: float
    timestamp: datetime


class StreamChunk(BaseModel):
    type: Literal["status", "reasoning", "source", "synthesis", "complete", "error"]
    content: Optional[str] = None
    data: Optional[Dict[str, Any]] = None
    timestamp: datetime = Field(default_factory=datetime.utcnow)


class AIClients:
    _instance: Optional['AIClients'] = None
    _initialized: bool = False

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        if not self._initialized:
            self.exa = Exa(api_key=settings.EXA_API_KEY)
            self.cerebras = Cerebras(api_key=settings.CEREBRAS_API_KEY, timeout=120.0, max_retries=3)
            self.grok = AsyncOpenAI(api_key=settings.XAI_API_KEY, base_url="", timeout=120.0, max_retries=3)
            self._initialized = True


ai_clients = AIClients()


class AdaptiveModelRouter:
    MODEL_CONFIGS = {
        ModelTier.FAST: {
            "grok_model": "grok-4-fast-non-reasoning",
            "grok_max_tokens": 16384,
            "cerebras_model": "qwen-3-32b",
            "cerebras_max_tokens": 32000,
            "temperature": 0.5,
            "exa_results_per_query": 10
        },
        ModelTier.BALANCED: {
            "grok_model": "grok-4-fast-reasoning",
            "grok_max_tokens": 32768,
            "cerebras_model": "gpt-oss-120b",
            "cerebras_max_tokens": 65000,
            "temperature": 0.3,
            "exa_results_per_query": 20
        },
        ModelTier.PREMIUM: {
            "grok_model": "grok-4-0709",
            "grok_max_tokens": 65536,
            "cerebras_model": "qwen-3-235b-a22b-thinking-2507",
            "cerebras_max_tokens": 32000,
            "temperature": 0.3,
            "exa_results_per_query": 30
        }
    }

    def get_model_config(self, tier: ModelTier) -> Dict[str, Any]:
        return self.MODEL_CONFIGS[tier]


class ExaService:
    def __init__(self):
        self.client = ai_clients.exa

    @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
    async def search_with_content(
        self,
        query: str,
        num_results: int = 20,
        livecrawl: str = "preferred",
        include_domains: Optional[List[str]] = None,
        exclude_domains: Optional[List[str]] = None
    ) -> Dict[str, Any]:
        search_params = {
            "query": query,
            "num_results": num_results,
            "type": "auto",
            "text": {"max_characters": 10000},
            "highlights": {"num_sentences": 5, "highlights_per_url": 10},
            "livecrawl": livecrawl
        }

        if include_domains:
            search_params["include_domains"] = include_domains
        if exclude_domains:
            search_params["exclude_domains"] = exclude_domains

        loop = asyncio.get_event_loop()
        result = await loop.run_in_executor(None, lambda: self.client.search_and_contents(**search_params))

        return {
            "results": [
                {
                    "url": r.url,
                    "title": r.title,
                    "text": getattr(r, 'text', None),
                    "highlights": getattr(r, 'highlights', []),
                    "score": getattr(r, 'score', None)
                }
                for r in result.results
            ]
        }


class GrokService:
    def __init__(self):
        self.client = ai_clients.grok

    @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
    async def analyze_strategy(
        self,
        query: str,
        model: str = "grok-4-fast-reasoning",
        max_tokens: int = 32768,
        temperature: float = 0.3
    ) -> Dict[str, Any]:
        system_prompt = """You are a strategic research planner. Create comprehensive research strategy.

Output JSON with:
- research_angles: 5-10 specific research angles
- search_queries: 5-10 optimized search queries
- key_domains: authoritative domains to prioritize"""

        response = await self.client.chat.completions.create(
            model=model,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": f"Create research strategy: {query}"}
            ],
            temperature=temperature,
            max_tokens=max_tokens,
            response_format={"type": "json_object"}
        )

        strategy = json.loads(response.choices[0].message.content)

        return {
            "strategy": strategy,
            "tokens_used": response.usage.total_tokens
        }


class CerebrasService:
    def __init__(self):
        self.client = ai_clients.cerebras

    @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
    def stream_synthesis(
        self,
        context: str,
        instruction: str,
        model: str = "gpt-oss-120b",
        max_tokens: int = 65000
    ):
        messages = [
            {
                "role": "system",
                "content": "You are an expert research synthesizer. Create comprehensive analysis with citations."
            },
            {
                "role": "user",
                "content": f"Context:\n{context}\n\nInstruction: {instruction}"
            }
        ]

        stream = self.client.chat.completions.create(
            model=model,
            messages=messages,
            max_tokens=max_tokens,
            temperature=0.3,
            stream=True
        )

        for chunk in stream:
            if chunk.choices[0].delta.content:
                yield chunk.choices[0].delta.content


class HyperionOrchestrator:
    def __init__(self):
        self.exa = ExaService()
        self.grok = GrokService()
        self.cerebras = CerebrasService()
        self.router = AdaptiveModelRouter()

    async def execute_research(self, request: ResearchRequest) -> AsyncIterator[StreamChunk]:
        start_time = time.time()
        total_tokens = {"grok": 0, "cerebras": 0, "exa": 0}

        try:
            yield StreamChunk(
                type="status",
                content="Lekérdezés elemzése és kutatási stratégia tervezése..."
            )

            config = self.router.get_model_config(request.model_tier)

            yield StreamChunk(
                type="status",
                content=f"{request.model_tier.value.upper()} tier modellek használata"
            )

            strategy_result = await self.grok.analyze_strategy(
                query=request.query,
                model=config["grok_model"],
                max_tokens=config["grok_max_tokens"],
                temperature=config["temperature"]
            )

            strategy = strategy_result["strategy"]
            total_tokens["grok"] += strategy_result["tokens_used"]

            yield StreamChunk(
                type="reasoning",
                content="Kutatási stratégia elkészült",
                data={"strategy": strategy}
            )

            yield StreamChunk(
                type="status",
                content=f"Intelligencia gyűjtés {min(request.max_sources, len(strategy.get('search_queries', [])))} forrásból..."
            )

            search_tasks = []
            for query in strategy.get("search_queries", [request.query])[:5]:
                search_tasks.append(
                    self.exa.search_with_content(
                        query=query,
                        num_results=request.max_sources // 5,
                        livecrawl="preferred" if request.real_time else "fallback",
                        include_domains=request.domains,
                        exclude_domains=request.exclude_domains
                    )
                )

            search_results = await asyncio.gather(*search_tasks, return_exceptions=True)

            all_sources = []
            for result in search_results:
                if isinstance(result, dict) and "results" in result:
                    all_sources.extend(result["results"])
                    yield StreamChunk(
                        type="source",
                        content=f"{len(result['results'])} releváns forrás megtalálva"
                    )

            yield StreamChunk(
                type="status",
                content=f"{len(all_sources)} forrás szintetizálása ultra-gyors feldolgozással..."
            )

            context_parts = []
            for idx, source in enumerate(all_sources[:request.max_sources]):
                source_text = source.get("text", "")
                if source_text:
                    context_parts.append(
                        f"Forrás {idx + 1}: {source['title']}\n"
                        f"URL: {source['url']}\n"
                        f"Tartalom: {source_text[:2000]}\n"
                    )

            full_context = "\n\n".join(context_parts)

            synthesis_instruction = f"""Készíts átfogó kutatási szintézist a következő kérdésre: "{request.query}"

Az elemzett források alapján adj:
1. Vezetői összefoglalót
2. Főbb megállapításokat (forrás hivatkozásokkal)
3. Részletes elemzést
4. Megbízhatósági értékelést
5. További kutatást igénylő területeket

Használj inline hivatkozásokat mint [Forrás 1], [Forrás 2], stb."""

            synthesis_chunks = []
            for chunk in await asyncio.to_thread(
                lambda: list(self.cerebras.stream_synthesis(
                    context=full_context,
                    instruction=synthesis_instruction,
                    model=config["cerebras_model"],
                    max_tokens=config["cerebras_max_tokens"]
                ))
            ):
                synthesis_chunks.append(chunk)
                yield StreamChunk(
                    type="synthesis",
                    content=chunk
                )

            final_synthesis = "".join(synthesis_chunks)

            citations = [
                Citation(
                    url=src["url"],
                    title=src.get("title"),
                    snippet=src.get("text", "")[:200] if src.get("text") else None
                )
                for src in all_sources[:request.max_sources]
            ]

            processing_time = time.time() - start_time
            cost_estimate = (
                (total_tokens["grok"] / 1_000_000) * 0.20 +
                (len(final_synthesis.split()) * 1.3 / 1_000_000) * 0.75 +
                (len(all_sources) * 0.005)
            )

            result = ResearchResult(
                synthesis=final_synthesis,
                citations=citations,
                sources_analyzed=len(all_sources),
                tokens_used=total_tokens,
                cost_estimate=cost_estimate,
                processing_time=processing_time,
                timestamp=datetime.utcnow()
            )

            yield StreamChunk(
                type="complete",
                content="Kutatás sikeresen befejezve",
                data=result.model_dump()
            )

        except Exception as e:
            yield StreamChunk(
                type="error",
                content=f"Kutatás sikertelen: {str(e)}"
            )


app = FastAPI(title="Hyperion Research Platform API", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

orchestrator = HyperionOrchestrator()


@app.get("/", response_class=HTMLResponse)
async def root():
    html_path = os.path.join(os.path.dirname(__file__), "index.html")
    with open(html_path, "r", encoding="utf-8") as f:
        return f.read()


@app.post("/api/v1/research/stream")
async def stream_research(request: ResearchRequest):
    async def event_generator():
        try:
            async for chunk in orchestrator.execute_research(request):
                yield f"event: {chunk.type}\ndata: {json.dumps({'type': chunk.type, 'content': chunk.content, 'data': chunk.data, 'timestamp': chunk.timestamp.isoformat()})}\n\n"
        except Exception as e:
            yield f"event: error\ndata: {json.dumps({'type': 'error', 'content': str(e), 'timestamp': datetime.utcnow().isoformat()})}\n\n"

    return StreamingResponse(event_generator(), media_type="text/event-stream")


@app.get("/api/v1/health")
async def health_check():
    return {"status": "healthy", "timestamp": datetime.utcnow().isoformat()}


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
